function Hash([string]$rel){$p=Join-Path $ProjectRoot $rel;if(-not(Test-Path -LiteralPath $p -PathType Leaf)){throw "Missing checkpoint input: $rel"};$f=Get-Item -LiteralPath $p;[ordered]@{path=$rel.Replace('\','/');bytes=[int64]$f.Length;sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $p).Hash.ToLowerInvariant()}}
