$prior.core.version='2.7.4';$prior.core.describedVersion='2.7.4.0';$prior.core.executable='dist/orchestrator/win-x64/v2.7.4/KnowledgeClipper.Orchestrator.exe';$coreHash=Hash $prior.core.executable;$prior.core.bytes=$coreHash.bytes;$prior.core.sha256=$coreHash.sha256.ToUpperInvariant()
