$totalBytes=[int64](($treeFiles|ForEach-Object {[int64]$_.bytes}|Measure-Object -Sum).Sum);$prior.tree=[ordered]@{algorithm='ordinal relative path; path TAB bytes TAB lowercase sha256; LF; SHA-256 UTF-8';fileCount=$treeFiles.Count;totalBytes=$totalBytes;treeSha256=$treeHash;files=$treeFiles}
